interface.definition:
a!localVariables(
  local!isOldVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn) < #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false
    )
  ),
  local!regionId: if(
    toboolean(local!isOldVersion) = true,
    if(
      ri!nomination.originatingRegion = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[1],
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206289",
      if(
        ri!nomination.originatingRegion = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[2],
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
        null
      )
    ),
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11596299"
  ),
  local!oldBU,
  local!oldOffice,
  local!validRegionDropdown: {
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[1],
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[2],
    #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3566688",
    #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3566706",
    #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
  },
  local!updatedRegionDropdown: if(
    contains(
      local!validRegionDropdown,
      ri!nomination.originatingRegion
    ),
    local!validRegionDropdown,
    reject(
      fn!isnull,
      append(
        local!validRegionDropdown,
        ri!nomination.originatingRegion
      )
    )
  ),
  local!buId: 
  intersection(
    tointeger(
      property(
        index(
          ri!originatingBU,
          wherecontains(
            ri!nomination.originatingBU,
            touniformstring(index(ri!originatingBU,"bu",{}))
          ),
          null
        ),
        "buId",
        null
      )),
      tointeger(property(
        index(
          ri!originatingBU,
          wherecontains(
            tostring(local!regionId),
            touniformstring(index(ri!originatingBU,"regionId",{}))
          ),
          null
        ),
        "buId",
        null
      ))
  ),
  local!busForDropdown: if(
    a!isNullOrEmpty(local!regionId),
    {
      #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
    },
    touniformstring(
      property(
        index(
          ri!originatingBU,
          wherecontains(
            tointeger(local!regionId),
            tointeger(index(ri!originatingBU, "regionId", {}))
          ),
          null
        ),
        "bu",
        {}
      ),
      if(
        toboolean(local!isOldVersion) = true,
        #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        null
      ),
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
    )
  ),
  local!updatedOriginatingBUDropdown: if(
    contains(
      local!busForDropdown,
      ri!nomination.originatingBU
    ),
    local!busForDropdown,
    if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!oldBU),
    reject(
      fn!isnull,
      append(
        local!busForDropdown,
        ri!nomination.originatingBU
      )
    ),
    local!busForDropdown
    )
  ),
  local!officeForDropdown: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!regionId),
    union(
      index(ri!offices, "office", null),
      touniformstring({})
    ),
    property(
      index(
        ri!offices,
        wherecontains(
          local!buId,
          tointeger(index(ri!offices, "buId", {}))
        ),
        null
      ),
      "office",
      {}
    )
  ),
  local!validHomeOfficeDropdown: touniformstring(
    reject(
      fn!isnull,
      {
        local!officeForDropdown,
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185",
        #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630"
      }
    )
  ),
  local!updatedHomeOfficeDropdown: if(
    contains(
      local!validHomeOfficeDropdown,
      ri!nomination.originatingHomeOffice
    ),
    local!validHomeOfficeDropdown,
    if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!oldOffice),
    reject(
      fn!isnull,
      append(
        local!validHomeOfficeDropdown,
        ri!nomination.originatingHomeOffice
      )
    ),
    local!validHomeOfficeDropdown
    )
  ),
  local!refData: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId: {
      #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3920066",
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648661"
    },
    returnCDT: true,
    isActive: true
  ),
  local!jobFunctionDropdownData: index(
    local!refData,
    wherecontains(
      #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3920066",
      index(local!refData, "refTypeId", {})
    ),
    "description",
    {}
  ),
  local!jobFamilyDropdownData: index(
    local!refData,
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648661",
      index(local!refData, "refTypeId", {})
    ),
    "description",
    {}
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    style: "STANDARD",
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Candidate First Name",
                required: true,
                value: ri!nomination.firstName,
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                saveInto: { ri!nomination.firstName }
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Employee ID",
                value: ri!nomination.employeeId,
                characterLimit: 12,
                saveInto: { ri!nomination.employeeId }
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Job Family",
                value: ri!nomination.levelName,
                choiceLabels: local!jobFamilyDropdownData,
                choiceValues: local!jobFamilyDropdownData,
                saveInto: { ri!nomination.levelName },
                placeholder: "-- Select Job Family --"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Candidate Last Name",
                required: true,
                value: ri!nomination.lastName,
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                saveInto: { ri!nomination.lastName }
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Job Function",
                value: ri!nomination.functionName,
                choiceLabels: local!jobFunctionDropdownData,
                choiceValues: local!jobFunctionDropdownData,
                saveInto: { ri!nomination.functionName },
                placeholder: "-- Select Job Function --"
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Job Description",
                value: ri!nomination.jobDescription,
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958027",
                saveInto: { ri!nomination.jobDescription }
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Originating Region",
                showWhen: if(
                  toboolean(local!isOldVersion) = true,
                  true,
                  false
                ),
                placeholder: "-- Select Region --",
                choiceLabels: local!updatedRegionDropdown,
                choiceValues: local!updatedRegionDropdown,
                value: ri!nomination.originatingRegion,
                saveInto: {
                  ri!nomination.originatingRegion,
                  a!save(ri!nomination.returnRegion, save!value),
                  if(
                    ri!nomination.originatingRegion <> #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    {
                      a!save(
                        ri!nomination.otherOriginatingRegion,
                        null
                      ),
                      a!save(
                        ri!nomination.otherReturningRegion,
                        null
                      )
                    },
                    null
                  ),
                  if(
                    contains(
                      {
                        #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3566688",
                        #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3566706",
