                validations: if(
                  or(
                    contains(
                      local!busForDropdown,
                      ri!nomination.originatingBU
                    ),
                    a!isNullOrEmpty(ri!nomination.originatingBU)
                  ),
                  "",
                  "Please select a valid originating BU"
                )
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Originating Home Office",
                placeholder: "-- Select Home Office --",
                choiceLabels: local!updatedHomeOfficeDropdown,
                choiceValues: local!updatedHomeOfficeDropdown,
                value: ri!nomination.originatingHomeOffice,
                saveInto: {
                  a!save(local!oldOffice,ri!nomination.originatingHomeOffice),
                  ri!nomination.originatingHomeOffice,
                  a!save(
                    ri!nomination.returnHomeOffice,
                    save!value
                  ),
                  if(
                    ri!nomination.originatingHomeOffice <> #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    {
                      a!save(
                        ri!nomination.otherOriginatingHomeOffice,
                        null
                      ),
                      a!save(
                        ri!nomination.otherReturningHomeOffice,
                        null
                      )
                    },
                    {}
                  )
                },
                validations: if(
                  or(
                    contains(
                      local!validHomeOfficeDropdown,
                      ri!nomination.originatingHomeOffice
                    ),
                    a!isNullOrEmpty(ri!nomination.originatingHomeOffice)
