                value: ri!nomination.otherOriginatingBU,
                saveInto: { ri!nomination.otherOriginatingBU },
                disabled: not(
                  ri!nomination.originatingBU = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630"
                ),
                characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                validations: if(
                  regexmatch(
                    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11586353",
